Real Locomotor::getMaxTurnRate(Object *obj) const
{
	Real turnRate;
	if (obj->getBodyModule()->getDamageState() < TheWritableGlobalData->m_movementPenaltyDamageState)
		turnRate = 6.28318548f / (Real)m_template->m_turnTime;
	else
		turnRate = 6.28318548f / (Real)m_template->m_turnTimeDamaged;
	if (turnRate > m_unk0x38)
		turnRate = m_unk0x38;
	return turnRate;
}

