// Zero Hour's lift (m_maxLift): Lift or LiftDamaged by the damage state, per frame squared,
// scaled by the AI's speed factor and capped by +0x24. Provisional name.
Real Locomotor::getMaxLift(Object *obj, Int damageState)
{
	Real scale = obj->getAI()->m_unk0x1F8;
	Real lift;
	if (damageState < TheWritableGlobalData->m_movementPenaltyDamageState)
		lift = (g_secondsPerLogicFrame * g_secondsPerLogicFrame) * m_template->m_lift;
	else
		lift = (g_secondsPerLogicFrame * g_secondsPerLogicFrame) * m_template->m_liftDamaged;
	lift *= scale;
	if (lift > m_unk0x24)
		lift = m_unk0x24;
	return lift;
}

