// FUNCTION: BFME2 0x001E4073 size=102 name=?rva001E4073@Rva001E4073@@QAEMPAVObject@@PAM@Z evidence=?:placeholder tier=A
// Zero Hour's calcMinTurnRadius, from the object rather than a damage state.
Real Locomotor::calcMinTurnRadius(Object *obj, Real *timeToTravelThatDist)
{
	Real minSpeed = getMinSpeed(obj);					// in dist/frame
	Real maxTurnRate = getMaxTurnRate(obj);				// in rads/frame

	// if we can't turn, return a huge-but-finite radius rather than NAN...
	Real minTurnRadius = (maxTurnRate > 0.0f) ? minSpeed / maxTurnRate : 99999.0f;

	if (timeToTravelThatDist)
		*timeToTravelThatDist = (minSpeed > 0.0f) ? (minTurnRadius / minSpeed) : 0.0f;

	return minTurnRadius;
}

