// FUNCTION: BFME2 0x001E468F size=82 name=?rva001E468F@Rva001E468F@@QAE_NPAVObject@@@Z evidence=?:placeholder tier=A
Bool Locomotor::isChargeSpeedActive(Object *obj)
{
	if (m_template->m_chargeAvailable)
	{
		if (obj->testStatus((ObjectStatusTypes)0x16) || obj->testStatus((ObjectStatusTypes)0x1e))
			return true;
	}
	if (obj != 0 && obj->m_hasChargeAttackAbility && obj->rva00293926((KindOfType)0x84))
		return true;
	return false;
}


// FUNCTION: BFME2 0x001E46E1 size=356 name=?getMaxSpeed@Locomotor@@QBEMPAVObject@@@Z evidence=N:ledger tier=A
Real Locomotor::getMaxSpeed(Object *obj) const
{
	Int damageState = obj->getBodyModule()->getDamageState();
	Real scale = obj->getAI()->m_unk0x1F8;
	Real speed;
	if (damageState >= TheWritableGlobalData->m_movementPenaltyDamageState && !m_template->m_chargeIgnoresCondition)
		speed = m_template->m_speedDamaged * g_secondsPerLogicFrame * scale;
	else if (const_cast<Locomotor *>(this)->isChargeSpeedActive(obj))
		speed = m_template->m_chargeSpeed * g_secondsPerLogicFrame * scale;
	else
		speed = g_secondsPerLogicFrame * scale;
	if (speed > m_unk0x28)
		speed = m_unk0x28;
	if (m_template->m_crewPowered)
		speed *= obj->rva0028B842();
	Real crewScale = 0.0f;
	if (obj->rva0028C15E(8, &crewScale, 0, 1))
		speed = crewScale * speed;
	if (m_template->m_riverModifier != 1.0f)
	{
		Bool flag = false;
		if (TheTerrainLogic->isUnderwater(obj->getPosition()->x, obj->getPosition()->y, 0, 0, &flag) && flag)
			speed = m_template->m_riverModifier * speed;
	}
	if (m_unk0x2C != -1.0f)
	{
		if (!(m_unk0x2C > speed))
			speed = m_unk0x2C;
	}
	return speed;
}


