// FUNCTION: BFME2 0x001E525A size=382 name=?xfer@Locomotor@@MAEXPAVXfer@@@Z evidence=N:ledger tier=A
void Locomotor::xfer(Xfer *xfer)
{
	if (xfer->IsLightCRC())
		return;
	Xfer::Version version(1, 3);
	*xfer == version;
	*xfer == m_unk0x08;
	*xfer == m_unk0x20;
	*xfer == m_unk0x24;
	*xfer == m_unk0x28;
	*xfer == m_unk0x30;
	*xfer == m_unk0x34;
	*xfer == m_unk0x38;
	*xfer == m_closeEnoughDist;
	*xfer == m_unk0x40;
	*xfer == m_flags;
	*xfer == m_preferredHeight;
	*xfer == m_preferredAttackHeight;
	*xfer == m_preferredHeightDamping;
	*xfer == m_unk0x54;
	*xfer == m_unk0x58;
	*xfer == m_unk0x98;
	*xfer == m_unk0xA0;
	*xfer == m_unk0xA4;
	*xfer == m_unk0x14;
	*xfer == m_unk0x5C;
	*xfer == m_unk0x60;
	*xfer == m_unk0x64;
	*xfer == m_unk0x99;
	xfer->XferRawBytes(&m_airborneState, sizeof(m_airborneState));
	if (version.m_minimum > 1)
		*xfer == m_unk0x9A;
	if (version.m_minimum >= 3)
	{
		UnsignedInt unused = 0;
		*xfer == unused;
	}
}

// FUNCTION: BFME2 0x001E53D8 size=103 name=?rva001E53D8@Rva001E46E1@@QAEXMPAVObject@@@Z evidence=?:placeholder tier=A
void Locomotor::updateCurrentSpeed(Real targetSpeed, Object *obj)
{
	if (targetSpeed > m_unk0x40)
	{
		m_unk0x40 += getMaxAcceleration(obj);
		if (m_unk0x40 > targetSpeed)
			m_unk0x40 = targetSpeed;
	}
	else
		m_unk0x40 = targetSpeed;
	Real maxSpeed = getMaxSpeed(obj);
	Real speed = m_unk0x40;
	m_unk0x40 = speed < 0.0f ? 0.0f : (speed > maxSpeed ? maxSpeed : speed);
}

// FUNCTION: BFME2 0x001E543F size=44 name=?rva001E543F@Rva001E46E1@@QAE_NPAVObject@@@Z evidence=?:placeholder tier=A
Int Locomotor::isAboveQuarterSpeed(Object *obj)
{
	Real current = m_unk0x40;
	if (current > getMaxSpeed(obj) * 0.25f)
		return 1;
	return 0;
}

