// FUNCTION: BFME2 0x001E5F1D size=234 name=?rva001E5F1D@Rva001E46E1@@QAE_NPAVObject@@PBVCoord3D@@PAM@Z evidence=X:retail PE exports class Coord3D: ??0Matrix4D@@QAE@ABVCoord3D@@@Z tier=A
// On the ground layer and in water deeper than a quarter of the AI's WadeWaterDepth, set
// condition 239 (clearing 240), or both 240 and 239 past the full depth, and answer true;
// otherwise clear both. waterZ is the water surface, *ground the terrain under it.
Bool Locomotor::updateWadeConditions(Object *obj, const Coord3D *pos, Real *ground)
{
	Real waterZ = 0.0f;
	if (obj->rva0028B511() == 1 && TheTerrainLogic->isUnderwater(pos->x, pos->y, &waterZ, ground, NULL))
	{
		const Real &wadeDepth = TheAI->getAiData()->m_wadeWaterDepth;
		Real depth = waterZ - *ground;
		if (depth > wadeDepth * 0.25f)
		{
			if (depth > wadeDepth)
			{
				obj->rva001E431E((const int *)&ModelConditionFlags(ModelConditionFlags::kInit, 240, 239));
			}
			else
			{
				obj->clearAndSetCondition(240, 239);
			}
			return true;
		}
	}
	obj->rva001E42F2((const int *)&ModelConditionFlags(ModelConditionFlags::kInit, 240, 239));
	return false;
}

