// FUNCTION: BFME2 0x001E70C2 size=312 name=?xferSelfAndCurLocoPtr@LocomotorSet@@QAEXPAVXfer@@PAPAVLocomotor@@@Z evidence=N:ledger tier=A
// The set, then the current locomotor by template name; on load the name picks the set's
// locomotor with that template (an unknown name is a corrupt save).
void LocomotorSet::xferSelfAndCurLocoPtr(Xfer *xfer, Locomotor **loco)
{
	xfer->Version1();
	*xfer == *this;
	if (xfer->IsStoring())
	{
		AsciiString name;
		if (*loco != NULL)
			name = (*loco)->getTemplateName();
		*xfer == name;
	}
	else
	{
		AsciiString name;
		*xfer == name;
		if (name.isEmpty())
		{
			*loco = NULL;
		}
		else
		{
			for (Int i = 0; i < m_locomotors.size(); ++i)
			{
				if (m_locomotors[i]->getTemplateName() == name)
				{
					*loco = m_locomotors[i];
					return;
				}
			}
			throw XferException(5, 0);
		}
	}
}

