// FUNCTION: BFME2 0x001E7C4C size=147 name=?rva001E7C4C@Rva001E7C4C@@QAEXPAVObject@@IMM@Z evidence=?:placeholder tier=A

// FUNCTION: BFME2 0x001E7CDF size=326 name=?maintainCurrentPositionWings@Locomotor@@IAEXPAVObject@@@Z evidence=N:ledger tier=A
// Zero Hour's maintainCurrentPositionWings without the physics argument: airborne, circle the
// maintain position at the circling radius (or the minimum turn radius) at minimum speed.
void Locomotor::maintainCurrentPositionWings(Object *obj)
{
	if (obj->isAboveTerrain())
	{
		m_flags |= (1 << NO_SLOW_DOWN_AS_APPROACHING_DEST);

		// aim for the spot on the opposite side of the circle.
		Real turnRadius = m_template->m_circlingRadius;
		if (turnRadius == 0.0f)
			turnRadius = calcMinTurnRadius(obj, NULL);

		// find the direction towards our "maintain pos"
		const Coord3D *pos = obj->getPosition();
		Real dx = m_unk0x08.x - pos->x;
		Real dy = m_unk0x08.y - pos->y;
		Real angleTowardMaintainPos =
				(isNearlyZero(dx) && isNearlyZero(dy)) ?
				obj->getOrientation() :
				atan2(dy, dx);

		Real aimDir = (3.14159265359f - 3.14159265359f/8);
		if (turnRadius < 0)
		{
			turnRadius = -turnRadius;
			aimDir = -aimDir;
		}
		angleTowardMaintainPos += aimDir;

		// project a spot "radius" dist away from it, in that dir
		Coord3D desiredPos;
		desiredPos.x = m_unk0x08.x;
		desiredPos.y = m_unk0x08.y;
		desiredPos.z = m_unk0x08.z;
		desiredPos.x += Cos(angleTowardMaintainPos) * turnRadius;
		desiredPos.y += Sin(angleTowardMaintainPos) * turnRadius;
		moveTowardsPositionWings(obj, desiredPos, 0, getMinSpeed(obj));
	}
}

// FUNCTION: BFME2 0x001E7E25 size=83 name=?rva001E7E25@Rva001E7E25@@QAEXXZ evidence=?:placeholder tier=A
void LocomotorSet::clear()
{
	for (UnsignedInt i = 0; i < m_locomotors.size(); ++i)
	{
		if (m_locomotors[i])
			::delete m_locomotors[i];
	}
	m_locomotors.clear();
	m_validLocomotorSurfaces = 0;
	m_downhillOnly = false;
	m_scalesWalls = false;
}

// FUNCTION: BFME2 0x001E7ECA size=1527 name=?rva001E7ECA@Locomotor@@QAE_NPAVObject@@PBVCoord3D@@@Z evidence=X:retail PE exports class Coord3D: ??0Matrix4D@@QAE@ABVCoord3D@@@Z tier=A

