void LocomotorSet::addLocomotor(const LocomotorTemplate *lt, Bool flag)
{
	Locomotor *loco = TheLocomotorStore->newLocomotor(lt, flag);
	if (loco)
	{
		m_locomotors.push_back(loco);
		m_validLocomotorSurfaces |= loco->m_template->m_surfaces;
		if (loco->m_template->m_downhillOnly)
			m_downhillOnly = true;
		if (loco->m_template->m_scalesWalls)
			m_scalesWalls = true;
	}
}

